{
  "command": "python3 -c "
import docx

doc = docx.Document('/app/output/result.docx')
print('=== Paragraph Count:', len(doc.paragraphs))
print('=== Table Count:', len(doc.tables))

# Check introductory paragraphs of Sections II, III, IV
sec_intros = {}
current_sec = None
for p in doc.paragraphs:
    txt = p.text.strip()
    if 'SECTION II:' in txt:
        current_sec = 'SEC_II'
    elif 'SECTION III:' in txt:
        current_sec = 'SEC_III'
    elif 'SECTION IV:' in txt:
        current_sec = 'SEC_IV'
    elif 'SECTION V:' in txt:
        current_sec = 'SEC_V'
    elif current_sec and current_sec not in sec_intros and txt and not txt.startswith('EXAMINATION') and not txt.startswith('ENGINEERING') and not txt.startswith('ATTORNEY'):
        sec_intros[current_sec] = txt

for k, v in sec_intros.items():
    sentences = [s.strip() for s in v.split('.') if s.strip()]
    print(f'{k} intro ({len(sentences)} sentences): {v[:100]}...')

# Check questions
q_count = 0
source_count = 0
purpose_count = 0
for p in doc.paragraphs:
    txt = p.text.strip()
    if txt.startswith('Q') and '.' in txt[:5]:
        q_count += 1
    elif txt.startswith('Source:'):
        source_count += 1
    elif txt.startswith('Evidentiary purpose:'):
        purpose_count += 1

print(f'Total Questions: {q_count}, Total Sources: {source_count}, Total Evidentiary Purposes: {purpose_count}')
"",
  "description": "Verify document structure, sentence counts and questions"
}

